import React, { useState } from "react";
import Navbar from "../components/Navbar";
import { api } from "../utils/api";
import { motion } from "framer-motion";

export default function Report() {
  const [loading, setLoading] = useState(false);
  const [ticketId, setTicketId] = useState("");

  const [form, setForm] = useState({
    fullName: "",
    phone: "",
    category: "WHATSAPP",
    message: "",
    link: "",
    upiId: "",
    suspectNumber: ""
  });

  const [screenshot, setScreenshot] = useState(null);

  async function submit(e) {
    e.preventDefault();
    setLoading(true);
    setTicketId("");

    try {
      const fd = new FormData();
      Object.keys(form).forEach((k) => fd.append(k, form[k]));
      if (screenshot) fd.append("screenshot", screenshot);

      const res = await api.post("/api/cases", fd, {
        headers: { "Content-Type": "multipart/form-data" }
      });

      setTicketId(res.data.ticketId);

      // Reset form
      setForm({
        fullName: "",
        phone: "",
        category: "WHATSAPP",
        message: "",
        link: "",
        upiId: "",
        suspectNumber: ""
      });
      setScreenshot(null);
    } catch (err) {
      alert(err?.response?.data?.message || "Failed to submit case");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 via-white to-gray-50">
      <Navbar />

      <div className="max-w-3xl mx-auto px-4 py-12">
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, ease: "easeOut" }}
        >
          <h2 className="text-4xl font-black tracking-tight">Scam Check</h2>
          <p className="text-gray-600 mt-2 text-lg">
            Submit link/message/UPI details. Our SOC will review and respond.
          </p>

          {ticketId && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.35 }}
              className="mt-6 bg-green-50 border border-green-200 rounded-3xl p-5"
            >
              <div className="font-black text-green-800 text-lg">
                ✅ Case submitted successfully
              </div>
              <div className="text-sm text-green-700 mt-2">
                Your ticket ID is:
              </div>
              <div className="mt-2 text-xl font-black">{ticketId}</div>
              <div className="mt-3 text-sm text-gray-700">
                Tip: Save this Ticket ID. You can also login later to track reply.
              </div>
            </motion.div>
          )}

          <motion.form
            onSubmit={submit}
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.55, delay: 0.05 }}
            className="mt-10 bg-white rounded-3xl shadow p-7 border space-y-5"
          >
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <div className="text-sm font-semibold mb-2">Full Name *</div>
                <input
                  className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                  placeholder="e.g. Sahil Nikam"
                  value={form.fullName}
                  onChange={(e) =>
                    setForm({ ...form, fullName: e.target.value })
                  }
                  required
                />
              </div>

              <div>
                <div className="text-sm font-semibold mb-2">Phone Number *</div>
                <input
                  className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                  placeholder="e.g. 9876543210"
                  value={form.phone}
                  onChange={(e) => setForm({ ...form, phone: e.target.value })}
                  required
                />
              </div>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">Category</div>
              <select
                className="w-full border rounded-2xl px-4 py-3 bg-white focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                value={form.category}
                onChange={(e) =>
                  setForm({ ...form, category: e.target.value })
                }
              >
                <option value="WHATSAPP">WhatsApp</option>
                <option value="UPI">UPI</option>
                <option value="INSTAGRAM">Instagram</option>
                <option value="SMS">SMS</option>
                <option value="CALL">Call</option>
                <option value="EMAIL">Email</option>
                <option value="WEBSITE">Website</option>
                <option value="OTHER">Other</option>
              </select>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">
                Explain what happened *
              </div>
              <textarea
                className="w-full border rounded-2xl px-4 py-3 min-h-[140px] focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                placeholder="Paste the scam message or explain full details..."
                value={form.message}
                onChange={(e) => setForm({ ...form, message: e.target.value })}
                required
              />
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">
                Suspicious Link (optional)
              </div>
              <input
                className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                placeholder="e.g. https://fake-offer.com"
                value={form.link}
                onChange={(e) => setForm({ ...form, link: e.target.value })}
              />
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <div className="text-sm font-semibold mb-2">
                  UPI ID (optional)
                </div>
                <input
                  className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                  placeholder="e.g. xyz@upi"
                  value={form.upiId}
                  onChange={(e) => setForm({ ...form, upiId: e.target.value })}
                />
              </div>

              <div>
                <div className="text-sm font-semibold mb-2">
                  Suspect Number (optional)
                </div>
                <input
                  className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                  placeholder="e.g. 9876543210"
                  value={form.suspectNumber}
                  onChange={(e) =>
                    setForm({ ...form, suspectNumber: e.target.value })
                  }
                />
              </div>
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">
                Upload Screenshot (optional)
              </div>

              <input
                type="file"
                accept="image/png,image/jpeg,image/webp"
                className="mt-1"
                onChange={(e) => setScreenshot(e.target.files?.[0] || null)}
              />

              <div className="text-xs text-gray-500 mt-2">
                Max 2MB (png/jpg/webp)
              </div>

              {screenshot && (
                <div className="text-xs text-gray-700 mt-2">
                  Selected: <b>{screenshot.name}</b>
                </div>
              )}
            </div>

            <button
              disabled={loading}
              className="w-full px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold hover:opacity-95 active:scale-[0.99] transition disabled:opacity-60"
            >
              {loading ? "Submitting..." : "Submit for Scam Check"}
            </button>

            <div className="text-xs text-gray-600 leading-relaxed">
              🔒 CyberRaksha never asks for OTP/password and we do not take
              remote access.
            </div>
